def test_threshold_counter_update_mapping_counts():
    tc = ThresholdCounter()
    tc.add('a')
    tc.update({'a': 3, 'b': 2, 'zero': 0})
    assert dict(tc.items()) == {'a': 4, 'b': 2}
    assert tc.total == 6
